    { id: 'e3', t: 'Визит — Услуга', sub: 'в визите несколько услуг, услуга встречается во многих визитах', ok: 'MN' },
    { id: 'e4', t: 'Филиал — Мастер', sub: 'мастер работает в одном филиале', ok: '1N' },
    { id: 'e5', t: 'Клиент — Карта лояльности', sub: 'у клиента не больше одной карты, карта — ровно одного клиента', ok: '11' }
